import os
from typing import List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


class PollyVoiceSelector:
    def __init__(self, region_name: Optional[str] = None):
        self.client = boto3.client("polly", region_name=region_name)

    def list_voices_for_locale(self, target_locale: str) -> List[dict]:
        try:
            paginator = self.client.get_paginator("describe_voices")
            matches = []
            for page in paginator.paginate():
                for voice in page.get("Voices", []):
                    if self._voice_matches_locale(voice, target_locale):
                        matches.append(
                            {
                                "Id": voice.get("Id"),
                                "LanguageCode": voice.get("LanguageCode"),
                                "LanguageName": voice.get("LanguageName"),
                                "Gender": voice.get("Gender"),
                                "SupportedEngines": voice.get("SupportedEngines", []),
                                "AdditionalLanguageCodes": voice.get("AdditionalLanguageCodes", []),
                            }
                        )
            return matches
        except (BotoCoreError, ClientError):
            return []

    def select_voice_for_locale(self, target_locale: str, preferred_gender: Optional[str] = None) -> Optional[dict]:
        voices = self.list_voices_for_locale(target_locale)
        if not voices:
            return None

        if preferred_gender:
            for voice in voices:
                if str(voice.get("Gender", "")).lower() == preferred_gender.lower():
                    return voice

        return voices[0]

    def _voice_matches_locale(self, voice: dict, target_locale: str) -> bool:
        target = target_locale.lower().replace("_", "-")
        language_code = str(voice.get("LanguageCode", "")).lower()
        additional_codes = [str(code).lower() for code in voice.get("AdditionalLanguageCodes", [])]

        return target == language_code or target in additional_codes or language_code.startswith(target.split("-")[0])


if __name__ == "__main__":
    locale = os.getenv("TARGET_LOCALE", "en-US")
    preferred_gender = os.getenv("PREFERRED_GENDER")  # e.g., Male or Female
    aws_region = os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")

    selector = PollyVoiceSelector(region_name=aws_region)
    selected = selector.select_voice_for_locale(locale, preferred_gender=preferred_gender)

    if selected:
        print(selected["Id"])
    else:
        print("")
